்க ஆங்கிலம்\u001Eஆங்கிலம் (யூஎஸ்)\u001Eமிடில் ஆங்கிலம்\u001Eஎஸ்பரேன்டோ\u001Eஸ்பானிஷ்\u001Eலத்தின் அமெரிக்க ஸ்பானிஷ்\u001Eஐரோப்பிய ஸ்பானிஷ்\u001Eமெக்ஸிகன் ஸ்பானிஷ்\u001Eஎஸ்டோனியன்\u001Eபாஸ்க்\u001Eஎவோன்டோ\u001Eபெர்ஷியன்\u001Eதாரி\u001Eஃபேங்க்\u001Eஃபான்டி\u001Eஃபுலா\u001Eஃபின்னிஷ்\u001Eஃபிலிபினோ\u001Eஃபிஜியன்\u001Eஃபரோயிஸ்\u001Eஃபான்\u001Eபிரெஞ்சு\u001Eகனடிய பிரெஞ்சு\u001Eஸ்விஸ் பிரஞ்சு\u001Eகஜுன் பிரெஞ்சு\u001Eமிடில் பிரெஞ்சு\u001Eபழைய பிரெஞ்சு\u001Eவடக்கு ஃப்ரிஸியான்\u001Eகிழக்கு ஃப்ரிஸியான்\u001Eஃப்ரியூலியன்\u001Eமேற்கு ஃப்ரிஷியன்\u001Eஐரிஷ்\u001Eகா\u001Eகாகௌஸ்\u001Eகன் சீனம்\u001Eகயோ\u001Eபயா\u001Eஸ்காட்ஸ் கேலிக்\u001Eகீஜ்\u001Eகில்பெர்டீஸ்\u001Eகாலிஸியன்\u001Eமிடில் ஹை ஜெர்மன்\u001Eக்வாரனி\u001Eபழைய ஹை ஜெர்மன்\u001Eகோன்டி\u001Eகோரோன்டலோ\u001Eகோதிக்\u001Eக்ரேபோ\u001Eபண்டைய கிரேக்கம்\u001Eஸ்விஸ் ஜெர்மன்\u001Eகுஜராத்தி\u001Eகுஸி\u001Eமேங்க்ஸ்\u001Eகுவிசின்\u001Eஹௌஸா\u001Eஹைடா\u001Eஹக்கா சீனம்\u001Eஹவாயியன்\u001Eதெற்கு ஹைடா\u001Eஹீப்ரூ\u001Eஇந்தி\u001Eஃபிஜி இந்தி\u001Eஹிலிகாய்னான்\u001Eஹிட்டைட்\u001Eமாங்க்\u001Eஹிரி மோட்டு\u001Eகுரோஷியன்\u001Eஅப்பர் சோர்பியான்\u001Eசியாங்க் சீனம்\u001Eஹைத்தியன் க்ரியோலி\u001Eஹங்கேரியன்\u001Eஹுபா\u001Eஹல்கோமெலம்\u001Eஆர்மேனியன்\u001Eஹெரேரோ\u001Eஇன்டர்லிங்வா\u001Eஇபான்\u001Eஇபிபியோ\u001Eஇந்தோனேஷியன்\u001Eஇன்டர்லிங்\u001Eஇக்போ\u001Eசிசுவான் ஈ\u001Eஇனுபியாக்\u001Eமேற்கு கனடிய இனுக்டிடுட்\u001Eஇலோகோ\u001Eஇங்குஷ்\u001Eஇடோ\u001Eஐஸ்லேண்டிக்\u001Eஇத்தாலியன்\u001Eஇனுகிடூட்\u001Eஜாப்பனீஸ்\u001Eலோஜ்பன்\u001Eநகொம்பா\u001Eமாசெம்\u001Eஜூதேயோ-பெர்ஷியன்\u001Eஜூதேயோ-அராபிக்\u001Eஜாவனீஸ்\u001Eஜார்ஜியன்\u001Eகாரா-கல்பாக்\u001Eகபாய்ல்\u001Eகாசின்\u001Eஜ்ஜூ\u001Eகம்பா\u001Eகாவி\u001Eகபார்டியன்\u001Eதையாப்\u001Eமகொண்டே\u001Eகபுவெர்தியானு\u001Eகோரோ\u001Eகாங்கோ\u001Eகைன்கேங்\u001Eகாஸி\u001Eகோதானீஸ்\u001Eகொய்ரா சீனீ\u001Eகிகுயூ\u001Eகுவான்யாமா\u001Eகசாக்\u001Eககோ\u001Eகலாலிசூட்\u001Eகலின்ஜின்\u001Eகெமெர்\u001Eகிம்புன்து\u001Eகன்னடம்\u001Eகொரியன்\u001Eகொமி-பெர்ம்யாக்\u001Eகொங்கணி\u001Eகோஸ்ரைன்\u001Eக்பெல்லே\u001Eகனுரி\u001Eகராசே-பல்கார்\u001Eகரேலியன்\u001Eகுருக்\u001Eகாஷ்மிரி\u001Eஷம்பாலா\u001Eபாஃபியா\u001Eகொலோக்னியன்\u001Eகுர்திஷ்\u001Eகும்யிக்\u001Eகுடேனை\u001Eகொமி\u001Eகார்னிஷ்\u001Eகுவாக்வாலா\u001Eகுவி\u001Eகிர்கிஸ்\u001Eலத்தின்\u001Eலடினோ\u001Eலங்கி\u001Eலஹன்டா\u001Eலம்பா\u001Eலக்ஸம்போர்கிஷ்\u001Eலெஜ்ஜியன்\u001Eகான்டா\u001Eலிம்பர்கிஷ்\u001Eலிகூரியன்\u001Eலில்லூயிட்\u001Eலகோடா\u001Eலொம்பார்டு\u001Eலிங்காலா\u001Eலாவோ\u001Eமோங்கோ\u001Eலூசியானா க்ரயோல்\u001Eலோசி\u001Eவடக்கு லுரி\u001Eசாமியா\u001Eலிதுவேனியன்\u001Eலுபா-கடாங்கா\u001Eலுபா-லுலுலா\u001Eலுய்சேனோ\u001Eலூன்டா\u001Eலுயோ\u001Eமிஸோ\u001Eலுயியா\u001Eலாட்வியன்\u001Eமதுரீஸ்\u001Eமகாஹி\u001Eமைதிலி\u001Eமகாசார்\u001Eமான்டிங்கோ\u001Eமாசாய்\u001Eமோக்க்ஷா\u001Eமான்டார்\u001Eமென்டீ\u001Eமெரு\u001Eமொரிசியன்\u001Eமலகாஸி\u001Eமிடில் ஐரிஷ்\u001Eமகுவா-மீட்டோ\u001Eமேடா\u001Eமார்ஷெலீஸ்\u001Eமௌரி\u001Eமிக்மாக்\u001Eமின்னாங்கபௌ\u001Eமாஸிடோனியன்\u001Eமலையாளம்\u001Eமங்கோலியன்\u001Eமன்சூ\u001Eமணிப்புரி\u001Eஇன்னு-ஐமுன்\u001Eமொஹாக்\u001Eமோஸ்ஸி\u001Eமராத்தி\u001Eமலாய்\u001Eமால்டிஸ்\u001Eமுன்டாங்\u001Eபல மொழிகள்\u001Eக்ரீக்\u001Eமிரான்டீஸ்\u001Eமார்வாரி\u001Eபர்மீஸ்\u001Eஏர்ஜியா\u001Eமசந்தேரனி\u001Eநவ்ரூ\u001Eமின் நான் சீனம்\u001Eநியோபோலிடன்\u001Eநாமா\u001Eநார்வேஜியன் பொக்மால்\u001Eவடக்கு தெபெலே\u001Eலோ ஜெர்மன்\u001Eலோ சாக்ஸன்\u001Eநேபாளி\u001Eநெவாரி\u001Eதோங்கா\u001Eநியாஸ்\u001Eநியூவான்\u001Eடச்சு\u001Eஃப்லெமிஷ்\u001Eக்வாசியோ\u001Eநார்வேஜியன் நியூநார்ஸ்க்\u001Eநெகெய்ம்பூன்\u001Eநார்வேஜியன்\u001Eநோகை\u001Eபழைய நோர்ஸ்\u001Eஎன்‘கோ\u001Eதெற்கு தெபெலே\u001Eவடக்கு சோதோ\u001Eநியூர்\u001Eநவாஜோ\u001Eபாரம்பரிய நேவாரி\u001Eநயன்ஜா\u001Eநியாம்வேஜி\u001Eநியான்கோலே\u001Eநியோரோ\u001Eநிஜ்மா\u001Eஒக்கிடன்\u001Eஒஜிப்வா\u001Eவடமேற்கு ஓஜிப்வா\u001Eமத்திய ஓஜிப்வா\u001Eஓஜி-க்ரீ\u001Eமேற்கு ஓஜிப்வா\u001Eஒகானகன்\u001Eஒரோமோ\u001Eஒடியா\u001Eஒசெட்டிக்\u001Eஓசேஜ்\u001Eஓட்டோமான் துருக்கிஷ்\u001Eபஞ்சாபி\u001Eபன்காசினன்\u001Eபாஹ்லவி\u001Eபம்பாங்கா\u001Eபபியாமென்டோ\u001Eபலௌவன்\u001Eநைஜீரியன் பிட்கின்\u001Eபென்சில்வேனிய ஜெர்மன்\u001Eபழைய பெர்ஷியன்\u001Eஃபொனிஷியன்\u001Eபாலி\u001Eபிஜின்\u001Eபோலிஷ்\u001Eஃபோன்பெயென்\u001Eமலிசீட்-பஸ்ஸமகுவாடி\u001Eபிரஷ்யன்\u001Eபழைய ப்ரோவென்சால்\u001Eபஷ்தோ\u001Eபோர்ச்சுகீஸ்\u001Eபிரேசிலிய போர்ச்சுகீஸ்\u001Eஐரோப்பிய போர்ச்சுகீஸ்\u001Eக்வெச்சுவா\u001Eகீசீ\u001Eராஜஸ்தானி\u001Eரபனுய்\u001Eரரோடோங்கன்\u001Eரோகிஞ்சா\u001Eரோமான்ஷ்\u001Eருண்டி\u001Eரோமேனியன்\u001Eமோல்டாவியன்\u001Eரோம்போ\u001Eரோமானி\u001Eரஷியன்\u001Eஅரோமானியன்\u001Eகின்யாருவான்டா\u001Eருவா\u001Eசமஸ்கிருதம்\u001Eசான்டாவே\u001Eசக்கா\u001Eசமாரிடன் அராமைக்\u001Eசம்புரு\u001Eசாசாக்\u001Eசான்டாலி\u001Eசௌராஷ்டிரம்\u001Eநெகாம்பே\u001Eசங்கு\u001Eசார்தீனியன்\u001Eசிசிலியன்\u001Eஸ்காட்ஸ்\u001Eசிந்தி\u001Eதெற்கு குர்திஷ்\u001Eவடக்கு சமி\u001Eசெனா\u001Eசெல்குப்\u001Eகொய்ராபோரோ சென்னி\u001Eசாங்கோ\u001Eபழைய ஐரிஷ்\u001Eசெர்போ-குரோஷியன்\u001Eதசேஹித்\u001Eஷான்\u001Eசிங்களம்\u001Eசிடாமோ\u001Eஸ்லோவாக்\u001Eஸ்லோவேனியன்\u001Eதெற்கு லுஷூட்சீட்\u001Eசமோவான்\u001Eதெற்கு சமி\u001Eலுலே சமி\u001Eஇனாரி சமி\u001Eஸ்கோல்ட் சமி\u001Eஷோனா\u001Eசோனின்கே\u001Eசோமாலி\u001Eசோக்தியன்\u001Eஅல்பேனியன்\u001Eசெர்பியன்\u001Eஸ்ரானன் டோங்கோ\u001Eசெரெர்\u001Eஸ்வாடீ\u001Eசஹோ\u001Eதெற்கு ஸோதோ\u001Eஸ்ட்ரெய்ட்ஸ் சாலிஷ்\u001Eசுண்டானீஸ்\u001Eசுகுமா\u001Eசுசு\u001Eசுமேரியன்\u001Eஸ்வீடிஷ்\u001Eஸ்வாஹிலி\u001Eகாங்கோ ஸ்வாஹிலி\u001Eகொமோரியன்\u001Eபாரம்பரிய சிரியாக்\u001Eசிரியாக்\u001Eசிலேசியன்\u001Eதமிழ்\u001Eதெற்கு டட்சோன்\u001Eதெலுங்கு\u001Eடிம்னே\u001Eடெசோ\u001Eடெரெனோ\u001Eடெடும்\u001Eதஜிக்\u001Eதகிஷ்\u001Eதாய்\u001Eதால்டன்\u001Eடிக்ரின்யா\u001Eடைக்ரே\u001Eடிவ்\u001Eதுருக்மென்\u001Eடோகேலௌ\u001Eடாகாலோக்\u001Eக்ளிங்கோன்\u001Eலிங்கிட்\u001Eதமஷேக்\u001Eஸ்வானா\u001Eடோங்கான்\u001Eநயாசா டோங்கா\u001Eடோக்கி போனா\u001Eடோக் பிஸின்\u001Eதுருக்கிஷ்\u001Eதரோகோ\u001Eஸோங்கா\u001Eட்ஸிம்ஷியன்\u001Eடாடர்\u001Eவடக்கு டட்சோன்\u001Eதும்புகா\u001Eடுவாலு\u001Eட்வி\u001Eடசவாக்\u001Eதஹிதியன்\u001Eடுவினியன்\u001Eமத்திய அட்லஸ் டமசைட்\u001Eஉட்முர்ட்\u001Eஉய்குர்\u001Eஉகாரிடிக்\u001Eஉக்ரைனியன்\u001Eஅம்பொண்டு\u001Eஅறியப்படாத மொழி\u001Eஉருது\u001Eஉஸ்பெக்\u001Eவை\u001Eவென்டா\u001Eவினிசியன்\u001Eவியட்நாமீஸ்\u001Eமகுவா\u001Eஒலாபூக்\u001Eவோட்க்\u001Eவுன்ஜோ\u001Eஒவாலூன்\u001Eவால்சேர்\u001Eவோலாய்ட்டா\u001Eவாரே\u001Eவாஷோ\u001Eவல்பிரி\u001Eஓலோஃப்\u001Eவூ சீனம்\u001Eகல்மிக்\u001Eஹோசா\u001Eகாங்கிரி\u001Eசோகா\u001Eயாவ்\u001Eயாபேசே\u001Eயாங்பென்\u001Eயெம்பா\u001Eயெட்டிஷ்\u001Eயோருபா\u001Eநஹீன்கட்டு\u001Eகாண்டோனீஸ்\u001Eஜுவாங்\u001Eஜாபோடெக்\u001Eப்லிஸ்ஸிம்பால்ஸ்\u001Eஜெனகா\u001Eஸ்டாண்டர்ட் மொராக்கன் தமாசைட்\u001Eசீனம்\u001Eஎளிதாக்கப்பட்ட சீனம்\u001Eபாரம்பரிய சீனம்\u001Eஜுலு\u001Eஜூனி\u001Eமொழி உள்ளடக்கம் ஏதுமில்லை\u001Eஜாஜா\u001F12அட்லாம்\u001Eஅரபிக்\u001Eநஸ்டாலிக்\u001Eஇம்பேரியல் அரமெய்க்\u001Eஅர்மேனியன்\u001Eஅவெஸ்தான்\u001Eபாலினீஸ்\u001Eபாடாக்\u001Eவங்காளம்\u001Eப்லிஸ்ஸிமிபால்ஸ்\u001Eபோபோமோஃபோ\u001Eபிரம்மி\u001Eபிரெயில்\u001Eபுகினீஸ்\u001Eபுகித்\u001Eசக்மா\u001Eஒருங்கிணைக்கப்பட்ட கனடிய பழங்குடி எழுத்துகள்\u001Eகரியன்\u001Eசாம்\u001Eசெரோக்கி\u001Eகிர்த்\u001Eகாப்டிக்\u001Eசைப்ரியாட்\u001Eசிரிலிக்\u001Eபழைய சர்ச் ஸ்லவோனிக் சிரிலிக்\u001Eதேவநாகரி\u001Eடெசராட்\u001Eஎகிப்தியன் டெமோட்டிக்\u001Eஎகிப்தியன் ஹைரேட்டிக்\u001Eஎகிப்தியன் ஹைரோகிளிப்ஸ்\u001Eஎத்தியோபிக்\u001Eஜியார்ஜியன் குட்சுரி\u001Eஜார்ஜியன்\u001Eக்லாகோலிடிக்\u001Eகோதிக்\u001Eகிரேக்கம்\u001Eகுஜராத்தி\u001Eகுர்முகி\u001Eஹன்ப்\u001Eஹங்குல்\u001Eஹன்\u001Eஹனுனூ\u001Eஎளிதாக்கப்பட்டது\u001Eபாரம்பரியம்\u001Eஹீப்ரு\u001Eஹிராகானா\u001Eபஹாவ் மாங்க்\u001Eஜப்பானிய எழுத்துருக்கள்\u001Eபழைய ஹங்கேரியன்\u001Eசிந்து\u001Eபழைய இத்தாலி\u001Eஜமோ\u001Eஜாவனீஸ்\u001Eஜப்பானியம்\u001Eகயாஹ் லீ\u001Eகதகானா\u001Eகரோஷ்டி\u001Eகமெர்\u001Eகன்னடம்\u001Eகொரியன்\u001Eகாய்தி\u001Eலன்னா\u001Eலாவோ\u001Eஃப்ரக்டூர் லெத்தின்\u001Eகேலிக் லெத்தின்\u001Eலத்தின்\u001Eலெப்சா\u001Eலிம்பு\u001Eலினியர் ஏ\u001Eலினியர் பி\u001Eலிசியன்\u001Eலிடியன்\u001Eமேன்டியன்\u001Eமனிசெய்ன்\u001Eமயான் ஹைரோகிளிப்\u001Eமெராய்டிக்\u001Eமலையாளம்\u001Eமங்கோலியன்\u001Eமூன்\u001Eமெய்தெய் மயக்\u001Eமியான்மர்\u001Eஎன்‘கோ\u001Eஒகாம்\u001Eஒல் சிக்கி\u001Eஆர்கான்\u001Eஒடியா\u001Eஒஸ்மான்யா\u001Eபழைய பெர்மிக்\u001Eபக்ஸ்-பா\u001Eஇன்ஸ்கிரிப்ஷனல் பஹலவி\u001Eசால்டர் பஹலவி\u001Eபுக் பஹலவி\u001Eஃபோனேஷியன்\u001Eபோலார்ட் ஃபொனெட்டிக்\u001Eஇன்ஸ்கிரிப்ஷனல் பார்த்தியன்\u001Eரெஜெய்ன்\u001Eஹனிஃபி\u001Eரொங்கோரொங்கோ\u001Eருனிக்\u001Eசமாரிடன்\u001Eசாராதி\u001Eசௌராஷ்ட்ரா\u001Eஸைன்எழுத்து\u001Eஷவியான்\u001Eசிங்களம்\u001Eசுந்தானீஸ்\u001Eசிலோடி நக்ரி\u001Eசிரியாக்\u001Eஎஸ்ட்ரெங்கெலோ சிரியாக்\u001Eமேற்கு சிரியாக்\u001Eகிழக்கு சிரியாக்\u001Eதகோவானா\u001Eதாய் லே\u001Eபுதிய தை லூ\u001Eதமிழ்\u001Eதை வியத்\u001Eதெலுங்கு\u001Eதெங்வார்\u001Eடிஃபினாக்\u001Eதகலாக்\u001Eதானா\u001Eதாய்\u001Eதிபெத்தியன்\u001Eஉகாரதிக்\u001Eவை\u001Eவிசிபிள் ஸ்பீச்\u001Eபழைய பெர்ஷியன்\u001Eசுமெரோ-அக்கடியன் க்யூனிஃபார்ம்\u001Eயீ\u001Eபாரம்பரியமான\u001Eகணிதக்குறியீடு\u001Eஎமோஜி\u001Eசின்னங்கள்\u001Eஎழுதப்படாதது\u001Eபொது\u001Eஅறியப்படாத ஸ்கிரிப்ட்\u001F08உலகம்\u001Eஆப்பிரிக்கா\u001Eவட அமெரிக்கா\u001Eதென் அமெரிக்கா\u001Eஓஷியானியா\u001Eமேற்கு ஆப்பிரிக்கா\u001Eமத்திய அமெரிக்கா\u001Eகிழக்கு ஆப்பிரிக்கா\u001Eவடக்கு ஆப்பிரிக்கா\u001Eமத்திய ஆப்பிரிக்கா\u001Eதெற்கு ஆப்பிரிக்கா\u001Eஅமெரிக்காஸ்\u001Eவடக்கு அமெரிக்கா\u001Eகரீபியன்\u001Eகிழக்கு ஆசியா\u001Eதெற்கு ஆசியா\u001Eதென்கிழக்கு ஆசியா\u001Eதெற்கு ஐரோப்பா\u001Eஆஸ்திரலேசியா\u001Eமெலனேஷியா\u001Eமைக்ரோனேஷியன் பிரதேசம்\u001Eபாலினேஷியா\u001Eஆசியா\u001Eமத்திய ஆசியா\u001Eமேற்கு ஆசியா\u001Eஐரோப்பா\u001Eகிழக்கு ஐரோப்பா\u001Eவடக்கு ஐரோப்பா\u001Eமேற்கு ஐரோப்பா\u001Eதுணை சஹாரா ஆப்பிரிக்கா\u001Eலத்தீன் அமெரிக்கா\u001Eஅஷன்ஷியன் தீவு\u001Eஅன்டோரா\u001Eஐக்கிய அரபு அமீரகம்\u001Eஆஃப்கானிஸ்தான்\u001Eஆண்டிகுவா மற்றும் பார்புடா\u001Eஅங்கியுலா\u001Eஅல்பேனியா\u001Eஅர்மேனியா\u001Eஅங்கோலா\u001Eஅண்டார்டிகா\u001Eஅர்ஜென்டினா\u001Eஅமெரிக்க சமோவா\u001Eஆஸ்திரியா\u001Eஆஸ்திரேலியா\u001Eஅரூபா\u001Eஆலந்து தீவுகள்\u001Eஅசர்பைஜான்\u001Eபோஸ்னியா & ஹெர்ஸகோவினா\u001Eபார்படாஸ்\u001Eபங்களாதேஷ்\u001Eபெல்ஜியம்\u001Eபுர்கினா ஃபாஸோ\u001Eபல்கேரியா\u001Eபஹ்ரைன்\u001Eபுருண்டி\u001Eபெனின்\u001Eசெயின்ட் பார்தேலெமி\u001Eபெர்முடா\u001Eபுருனே\u001Eபொலிவியா\u001Eகரீபியன் நெதர்லாந்து\u001Eபிரேசில்\u001Eபஹாமாஸ்\u001Eபூடான்\u001Eபொவேட் தீவு\u001Eபோட்ஸ்வானா\u001Eபெலாரஸ்\u001Eபெலிஸ்\u001Eகனடா\u001Eகோகோஸ் (கீலிங்) தீவுகள்\u001Eகாங்கோ - கின்ஷாசா\u001Eமத்திய ஆப்ரிக்கக் குடியரசு\u001Eகாங்கோ - ப்ராஸாவில்லே\u001Eஸ்விட்சர்லாந்து\u001Eகோட் தி’வாயர்\u001Eகுக் தீவுகள்\u001Eசிலி\u001Eகேமரூன்\u001Eசீனா\u001Eகொலம்பியா\u001Eகிலிப்பர்டன் தீவு\u001Eசார்க்\u001Eகோஸ்டாரிகா\u001Eகியூபா\u001Eகேப் வெர்டே\u001Eகுராகவ்\u001Eகிறிஸ்துமஸ் தீவு\u001Eசைப்ரஸ்\u001Eசெசியா\u001Eஜெர்மனி\u001Eடியகோ கார்ஷியா\u001Eஜிபௌட்டி\u001Eடென்மார்க்\u001Eடொமினிகா\u001Eடொமினிகன் குடியரசு\u001Eஅல்ஜீரியா\u001Eசியூடா & மெலில்லா\u001Eஈக்வடார்\u001Eஎஸ்டோனியா\u001Eஎகிப்து\u001Eமேற்கு சஹாரா\u001Eஎரிட்ரியா\u001Eஸ்பெயின்\u001Eஎத்தியோப்பியா\u001Eஐரோப்பிய யூனியன்\u001Eயூரோஜோன்\u001Eபின்லாந்து\u001Eஃபிஜி\u001Eஃபாக்லாந்து தீவுகள்\u001Eமைக்ரோனேஷியா\u001Eஃபாரோ தீவுகள்\u001Eபிரான்ஸ்\u001Eகேபான்\u001Eயுனைடெட் கிங்டம்\u001Eகிரனெடா\u001Eஜார்ஜியா\u001Eபிரெஞ்சு கயானா\u001Eகெர்ன்சி\u001Eகானா\u001Eஜிப்ரால்டர்\u001Eகிரீன்லாந்து\u001Eகாம்பியா\u001Eகினியா\u001Eக்வாதேலோப்\u001Eஈக்வடோரியல் கினியா\u001Eகிரீஸ்\u001Eதெற்கு ஜார்ஜியா மற்றும் தெற்கு சாண்ட்விச் தீவுகள்\u001Eகவுதமாலா\u001Eகுவாம்\u001Eகினியா-பிஸ்ஸாவ்\u001Eகயானா\u001Eஹாங்காங் எஸ்ஏஆர் சீனா\u001Eஹேர்ட் மற்றும் மெக்டொனால்டு தீவுகள்\u001Eஹோண்டூராஸ்\u001Eகுரோஷியா\u001Eஹைட்டி\u001Eஹங்கேரி\u001Eகேனரி தீவுகள்\u001Eஇந்தோனேசியா\u001Eஅயர்லாந்து\u001Eஇஸ்ரேல்\u001Eஐல் ஆஃப் மேன்\u001Eஇந்தியா\u001Eபிரிட்டிஷ் இந்தியப் பெருங்கடல் பிரதேசம்\u001Eஈராக்\u001Eஈரான்\u001Eஐஸ்லாந்து\u001Eஇத்தாலி\u001Eஜெர்சி\u001Eஜமைக்கா\u001Eஜோர்டான்\u001Eஜப்பான்\u001Eகென்யா\u001Eகிர்கிஸ்தான்\u001Eகம்போடியா\u001Eகிரிபாட்டி\u001Eகோமரோஸ்\u001Eசெயின்ட் கிட்ஸ் & நெவிஸ்\u001Eவட கொரியா\u001Eதென் கொரியா\u001Eகுவைத்\u001Eகெய்மென் தீவுகள்\u001Eகஸகஸ்தான்\u001Eலாவோஸ்\u001Eலெபனான்\u001Eசெயின்ட் லூசியா\u001Eலிச்செண்ஸ்டெய்ன்\u001Eஇலங்கை\u001Eலைபீரியா\u001Eலெசோதோ\u001Eலிதுவேனியா\u001Eலக்ஸ்சம்பர்க்\u001Eலாட்வியா\u001Eலிபியா\u001Eமொராக்கோ\u001Eமொனாக்கோ\u001Eமால்டோவா\u001Eமான்டேனெக்ரோ\u001Eசெயின்ட் மார்ட்டீன்\u001Eமடகாஸ்கர்\u001Eமார்ஷல் தீவுகள்\u001Eவடக்கு மாசிடோனியா\u001Eமாலி\u001Eமியான்மர் (பர்மா)\u001Eமங்கோலியா\u001Eமகாவ் எஸ்ஏஆர் சீனா\u001Eவடக்கு மரியானா தீவுகள்\u001Eமார்டினிக்\u001Eமௌரிடானியா\u001Eமாண்ட்செராட்\u001Eமால்டா\u001Eமொரிசியஸ்\u001Eமாலத்தீவு\u001Eமலாவி\u001Eமெக்சிகோ\u001Eமலேசியா\u001Eமொசாம்பிக்\u001Eநமீபியா\u001Eநியூ கேலிடோனியா\u001Eநைஜர்\u001Eநார்ஃபோக் தீவு\u001Eநைஜீரியா\u001Eநிகரகுவா\u001Eநெதர்லாந்து\u001Eநார்வே\u001Eநேபாளம்\u001Eநௌரு\u001Eநியுவே\u001Eநியூசிலாந்து\u001Eஓமன்\u001Eபனாமா\u001Eபெரு\u001Eபிரெஞ்சு பாலினேஷியா\u001Eபப்புவா நியூ கினியா\u001Eபிலிப்பைன்ஸ்\u001Eபாகிஸ்தான்\u001Eபோலந்து\u001Eசெயின்ட் பியர் & மிக்வேலான்\u001Eபிட்கெய்ர்ன் தீவுகள்\u001Eபியூர்டோ ரிகோ\u001Eபாலஸ்தீனிய பிரதேசங்கள்\u001Eபோர்ச்சுக்கல்\u001Eபாலோ\u001Eபராகுவே\u001Eகத்தார்\u001Eவெளிப்புற ஓஷியானியா\u001Eரீயூனியன்\u001Eருமேனியா\u001Eசெர்பியா\u001Eரஷ்யா\u001Eருவாண்டா\u001Eசவுதி அரேபியா\u001Eசாலமன் தீவுகள்\u001Eசீஷெல்ஸ்\u001Eசூடான்\u001Eஸ்வீடன்\u001Eசிங்கப்பூர்\u001Eசெயின்ட் ஹெலெனா\u001Eஸ்லோவேனியா\u001Eஸ்வல்பார்டு & ஜான் மேயன்\u001Eஸ்லோவாகியா\u001Eசியாரா லியோன்\u001Eசான் மரினோ\u001Eசெனெகல்\u001Eசோமாலியா\u001Eசுரினாம்\u001Eதெற்கு சூடான்\u001Eசாவ் தோம் & ப்ரின்சிபி\u001Eஎல் சால்வடார்\u001Eசின்ட் மார்டென்\u001Eசிரியா\u001Eஎஸ்வாட்டீனி\u001Eடிரிஸ்டன் டா குன்ஹா\u001Eடர்க்ஸ் & கைகோஸ் தீவுகள்\u001Eசாட்\u001Eபிரெஞ்சு தெற்கு பிரதேசங்கள்\u001Eடோகோ\u001Eதாய்லாந்து\u001Eதஜிகிஸ்தான்\u001Eடோகேலோ\u001Eதிமோர்-லெஸ்தே\u001Eதுர்க்மெனிஸ்தான்\u001Eடுனிசியா\u001Eடோங்கா\u001Eதுருக்கியே\u001Eடிரினிடாட் & டொபாகோ\u001Eதுவாலு\u001Eதைவான்\u001Eதான்சானியா\u001Eஉக்ரைன்\u001Eஉகாண்டா\u001Eயூ.எஸ். வெளிப்புறத் தீவுகள்\u001Eஐக்கிய நாடுகள்\u001Eஅமெரிக்கா\u001Eஉருகுவே\u001Eஉஸ்பெகிஸ்தான்\u001Eவாடிகன் நகரம்\u001Eசெயின்ட் வின்சென்ட் & கிரெனடைன்ஸ்\u001Eவெனிசுலா\u001Eபிரிட்டீஷ் கன்னித் தீவுகள்\u001Eயூ.எஸ். கன்னித் தீவுகள்\u001Eவியட்நாம்\u001Eவனுவாட்டு\u001Eவாலிஸ் மற்றும் ஃபுடுனா\u001Eசமோவா\u001Eபோலி உச்சரிப்புகள்\u001Eபோலி பீடி\u001Eகொசோவோ\u001Eஏமன்\u001Eமயோட்\u001Eதென் ஆப்பிரிக்கா\u001Eஜாம்பியா\u001Eஜிம்பாப்வே\u001Eஅறியப்படாத பிரதேசம்\u001F04\u001F0"

